abstract class Text {
    final String render() { return "<" + detail() + ">"; }
    abstract String detail();
}
class ChildText extends Text {
    @Override
    String detail() { return "CSE"; }
}

class Main {
    public static void main(String[] args) {
        Text text = new ChildText();
        System.out.println(text.render());
    }
}

abstract class Partial { Partial() { System.out.print("P"); } }
class Concrete extends Partial { Concrete() { System.out.println("C"); } }

class Main {
    public static void main(String[] args) {
        new Concrete();
    }
}

abstract class Counter {
    abstract int step();
    final int result() { return step() + step(); }
}
class DoubleStep extends Counter {
    private int value;
    @Override
    int step() { return ++value; }
}

class Main {
    public static void main(String[] args) {
        Counter counter = new DoubleStep();
        System.out.println(counter.result());
    }
}
